mkdir -p <local-path> cat > <local-path> <<'EOF'
import math,sys
def leg(a,b,slip=0.025):
    dx,dy=b[0]-a[0],b[1]-a[1]; d=math.hypot(dx,dy); h=math.degrees(math.atan2(dy,dx))%360
    return round(h,2), round(d,3), round(d/(1-slip),3)
pts=eval(sys.argv[1])
for i in range(len(pts)-1): print(pts[i],pts[i+1],leg(pts[i],pts[i+1]))
EOF
